function dropletRequest(config) {
  const required = (key) => {
    const value = config[key];
    if (typeof value !== "string" || !value.trim())
      throw new Error("Supply a nonempty " + key + ".");
    return value.trim();
  };
  const { image } = config;
  if (!(typeof image === "string" && image.trim()) && !(Number.isSafeInteger(image) && image > 0)) {
    throw new Error("Supply an image slug or positive integer image ID.");
  }
  const imageValue = typeof image === "string" ? image.trim() : image;
  const normalized =
    typeof imageValue === "string" && /^\d+$/.test(imageValue) ? Number(imageValue) : imageValue;
  if (typeof normalized === "number" && !(Number.isSafeInteger(normalized) && normalized > 0)) {
    throw new Error("Supply a positive integer image ID.");
  }
  return {
    name: required("name"),
    region: required("region"),
    size: required("size"),
    image: normalized,
  };
}
return [{ json: dropletRequest($input.first().json), pairedItem: { item: 0 } }];

function acceptedDroplet(status, body, expectedName) {
  if (
    status !== 202 ||
    !Number.isSafeInteger(body?.droplet?.id) ||
    body.droplet.id <= 0 ||
    body.droplet.name !== expectedName
  ) {
    throw new Error(
      "DigitalOcean did not return a matching acceptance receipt. Check the account before running again.",
    );
  }
  return {
    statusCode: status,
    accepted: true,
    dropletId: body.droplet.id,
    droplet: body.droplet,
    ...(body.links ? { links: body.links } : {}),
  };
}
const { statusCode, body } = $input.first().json;
return [
  {
    json: acceptedDroplet(
      statusCode,
      body,
      $("Validate Droplet parameters").itemMatching(0).json.name,
    ),
  },
];
